(* [comment removed for export] *)
Lemma cri_null_tail : forall C A m M1 md regs r2 (s msg : Z) kmsg (ret : word) (S : TSet) (kR bR w h : Z),
  Cok C -> W C A M1 md -> POSTM C A s m M1 ->
  (s mod 16 = 0)%Z -> (c_top C - LSTK + CRI_STACK <= s)%Z -> (s <= c_top C)%Z -> ret_ok ret ->
  getr regs 2 = Z_to_bv 64 s -> cellsZ M1 (frame5 s ret regs) ->
  getr r2 2 = Z_to_bv 64 (s - 80) -> getr r2 10 = Z_to_bv 64 msg -> getr r2 11 = Z_to_bv 64 0x1100d -> str16 msg kmsg ->
  (forall x, In x [3; 4; 20; 21; 22; 23; 24; 25; 26; 27]%bv -> getr r2 x = getr regs x) ->
  aroom A (m_vmmaps md) kR bR -> (RK_pix <= kR)%Z -> (RB_pixT (4 * (wpl_of w 32 * h)) <= bR)%Z ->
  (forall A' m' vm' regs', W C A' m' (with_vmmaps vm' md) -> cs_kept regs regs' -> POSTM C A s m m' ->
     ((getr regs' 10 = Z_to_bv 64 0 /\ forall q, live A' q = live A q)
      \/ (exists pixd datad, getr regs' 10 = Z_to_bv 64 pixd /\ pixr_new C A A' m' pixd datad (set_data (pix_hdr w h 32) datad))) ->
     aroom A' vm' (kR - RK_pix) (bR - RB_pixT (4 * (wpl_of w 32 * h))) ->
     realizes SEGS (mkCfg (mkst regs' ret m' al_rom) (with_vmmaps vm' md)) S) ->
